1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	const PROCESSING_FEE = 5;
13	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
14	
15	const BASE_PREMIUMS: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	  moonstone: 25,
22	};
23	
24	const COMPONENT_PREMIUM = 25;
25	const BLOCK_SIZE = 3;
26	const BLOCK_PREMIUM = 60;
27	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
28	
29	const basePremium = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;
30	
31	const componentsBasePremium = (count: number): number => {
32	  const blocks = Math.floor(count / BLOCK_SIZE);
33	  const remainder = count % BLOCK_SIZE;
34	  return blocks * BLOCK_PREMIUM + remainder * COMPONENT_PREMIUM;
35	};
36	
37	const applyFirstInsuranceSurcharge = (amount: number): number =>
38	  (amount * (100 + FIRST_INSURANCE_SURCHARGE_PERCENT)) / 100;
39	
40	const roundInMhpcoFavor = (premium: number): number => Math.ceil(premium);
41	
42	const itemsBasePremium = (items: Item[]): number => {
43	  const componentCount = items.filter((item) => COMPONENT_TYPES.has(item.type)).length;
44	  const mainItemsTotal = items
45	    .filter((item) => !COMPONENT_TYPES.has(item.type))
46	    .reduce((sum, item) => sum + basePremium(item), 0);
47	  return mainItemsTotal + componentsBasePremium(componentCount);
48	};
49	
50	export const quote = (
51	  customer: Customer,
52	  items: Item[],
53	  contractIndex: number,
54	): number => {
55	  const base = itemsBasePremium(items);
56	  return roundInMhpcoFavor(applyFirstInsuranceSurcharge(base) + PROCESSING_FEE);
57	};
58	
59	export const claim = (): number => {
60	  return undefined as unknown as number;
61	};
